// ============ CONFIGURACIÓN DEL CLIENTE (edita solo este bloque) ============
const CONFIG_BASE = {
  // --- quién emite la factura (sale tal cual en el PDF) ---
  emisor: {
    nombre: 'Tienda Demo, S.L.',
    nif: 'B00000000',
    direccion: 'Calle Ejemplo 1',
    cp_poblacion: '08001 Barcelona',
    pais: 'España',
    email: 'facturacion@tienda-demo.test',
    telefono: '',
  },

  fuente: 'demo',                 // 'demo', 'shopify' o 'woocommerce'
  documento: 'factura',           // 'factura', 'albaran' o 'ambos'

  serie: 'F',                     // prefijo del número: F2026-0001
  digitos: 4,                     // ceros a la izquierda del correlativo
  reiniciar_cada_anio: true,      // el correlativo vuelve a 1 en enero

  iva: 21,                        // tipo por defecto, si la línea no trae el suyo
  precios_con_iva: true,          // true = los precios de la tienda ya llevan IVA incluido
  moneda: 'EUR',

  enviar_al_cliente: true,        // false = solo se genera y se guarda, no se envía
  max_por_ejecucion: 25,
  texto_pie: 'Gracias por tu compra.',
  gotenberg_url: 'http://host.docker.internal:3000',

  email_from: 'facturacion@tu-dominio.com',   // remitente de las facturas
  email_to: 'cliente@ejemplo.com',            // a quién llega el RESUMEN diario
  telegram_chat_id: 'TU_CHAT_ID',
};
// ============================================================================

// ---- Panel único de Denoro: los ajustes del cliente llegan en la entrada ----
const __ENTRADA = $input.first().json || {};
const __limpio = (o) => Object.fromEntries(Object.entries(o || {}).filter(([, x]) => x !== '' && x !== null && x !== undefined));
const __mezclar = (b, o) => {
  const r = { ...b };
  for (const [k, v] of Object.entries(o || {})) {
    if (v && typeof v === 'object' && !Array.isArray(v) && b[k] && typeof b[k] === 'object' && !Array.isArray(b[k])) r[k] = { ...b[k], ...__limpio(v) };
    else if (v !== undefined && v !== null) r[k] = v;
  }
  return r;
};
const CONFIG = { ...__mezclar(CONFIG_BASE, __ENTRADA.config), __token: String(__ENTRADA.token || ''), __auto: String(__ENTRADA.auto || ''), __clave: String(__ENTRADA.clave || '') };
if (!CONFIG.__token || !CONFIG.__clave) throw new Error('Esta versión se lanza desde el panel de Denoro (falta el cliente)');
if (!['demo', 'shopify', 'woocommerce'].includes(CONFIG.fuente)) {
  throw new Error(`fuente "${CONFIG.fuente}" no válida: usa demo, shopify o woocommerce`);
}
if (!['factura', 'albaran', 'ambos'].includes(CONFIG.documento)) {
  throw new Error(`documento "${CONFIG.documento}" no válido: usa factura, albaran o ambos`);
}
// Una factura sin estos datos no es válida en España, así que mejor parar aquí.
for (const campo of ['nombre', 'nif', 'direccion', 'cp_poblacion']) {
  if (!String(CONFIG.emisor[campo] || '').trim()) {
    throw new Error(`Falta emisor.${campo}: una factura necesita el nombre fiscal, el NIF y el domicilio de quien la emite`);
  }
}
if (!/^[A-Z]?\d{7,8}[A-Z0-9]$/i.test(String(CONFIG.emisor.nif).replace(/[\s-]/g, ''))) {
  throw new Error(`El NIF "${CONFIG.emisor.nif}" no tiene una forma válida (p. ej. B12345678 o 12345678Z)`);
}
if (!String(CONFIG.serie || '').trim()) throw new Error('La serie no puede estar vacía');
if (!(CONFIG.digitos >= 1 && CONFIG.digitos <= 8)) throw new Error('digitos debe estar entre 1 y 8');
if (!(CONFIG.iva >= 0 && CONFIG.iva <= 100)) throw new Error('iva debe estar entre 0 y 100');
if (!(CONFIG.max_por_ejecucion >= 1 && CONFIG.max_por_ejecucion <= 200)) {
  throw new Error('max_por_ejecucion debe estar entre 1 y 200');
}
if (!/^https?:\/\//i.test(String(CONFIG.gotenberg_url || ''))) {
  throw new Error('gotenberg_url tiene que apuntar al servicio que convierte el HTML en PDF');
}
const PLACEHOLDER = /ejemplo\.com|tu-dominio|TU_CHAT_ID/i;
for (const k of ['email_to', 'email_from', 'telegram_chat_id']) {
  if (PLACEHOLDER.test(String(CONFIG[k] || ''))) {
    throw new Error(`Configura "${k}" en el nodo Configuración (ahora tiene un valor de ejemplo). Déjalo vacío ('') para desactivar ese canal.`);
  }
}
if (CONFIG.enviar_al_cliente && !CONFIG.email_from) {
  throw new Error('Falta email_from: sin remitente no se pueden enviar las facturas');
}
if (CONFIG.telegram_chat_id && !/^-?\d+$|^@\w+$/.test(String(CONFIG.telegram_chat_id))) {
  throw new Error('telegram_chat_id debe ser un número (p. ej. 123456789) o @canal');
}
if (!CONFIG.email_to && !CONFIG.telegram_chat_id) throw new Error('Configura al menos un canal para el resumen: email_to o telegram_chat_id');

return [{ json: {
  ...CONFIG,
  enviar_email: Boolean(CONFIG.email_to),
  enviar_telegram: Boolean(CONFIG.telegram_chat_id),
  ahora: new Date().toISOString(),
} }];

// Pedidos de ejemplo: uno de particular, uno de empresa con NIF, uno con dos tipos de IVA,
// uno sin email y uno ya facturado en una pasada anterior.
const cfg = $('Configuración').first().json;
const ahora = new Date(cfg.ahora).getTime();
const hace = (h) => new Date(ahora - h * 3600000).toISOString();
const L = (titulo, unidades, precio, iva) => ({ titulo, unidades, precio, iva });

const P = (id, numero, nombre, email, lineas, extra = {}) => ({ json: {
  id, numero_pedido: numero, fecha: hace(2),
  cliente: { nombre, email, nif: extra.nif || '', direccion: extra.direccion || 'Calle Falsa 1',
    cp_poblacion: extra.cp_poblacion || '28001 Madrid', pais: 'España' },
  lineas, envio: extra.envio ?? 4.95, descuento: extra.descuento ?? 0,
  moneda: cfg.moneda, pagado: extra.pagado ?? true,
} });

return [
  P('p-9001', 1001, 'Ana Ruiz', 'ana@ejemplo.test', [
    L('Botella térmica 750 ml', 2, 24.90), L('Taza de cerámica 350 ml', 1, 14.50)]),
  P('p-9002', 1002, 'Muebles Nord, S.L.', 'compras@nord.test', [
    L('Mesa de comedor extensible', 1, 449.00)], { nif: 'B12345678', direccion: 'Avinguda Diagonal 200', cp_poblacion: '08018 Barcelona', envio: 0 }),
  P('p-9003', 1003, 'Luis Sáez', 'luis@ejemplo.test', [
    L('Cuaderno de tapa dura A5', 3, 12.90, 21), L('Libro de recetas', 1, 19.90, 4)], { descuento: 5 }),
  P('p-9004', 1004, 'Marta Gil', '', [L('Vela de soja 220 g', 1, 26.00)]),
  P('p-9005', 1005, 'Pedro Lima', 'pedro@ejemplo.test', [L('Alfombrilla de escritorio', 1, 34.00)]),
  P('p-9006', 1006, 'Sara Vega', 'sara@ejemplo.test', [L('Sartén 28 cm', 1, 39.90)], { pagado: false }),
];

// Pedidos de Shopify con la forma que usa el resto del workflow.
const cfg = $('Configuración').first().json;
const salida = [];
for (const item of $input.all()) {
  const o = item.json;
  if (!o || !o.id) continue;
  const dir = o.billing_address || o.shipping_address || {};
  salida.push({ json: {
    id: String(o.id),
    numero_pedido: o.order_number || o.name || o.id,
    fecha: o.processed_at || o.created_at,
    cliente: {
      nombre: [dir.first_name, dir.last_name].filter(Boolean).join(' ') || dir.company || o.email || 'Cliente',
      email: (o.email || '').trim().toLowerCase(),
      nif: (o.note_attributes || []).find((a) => /nif|cif|vat|dni/i.test(a.name))?.value || '',
      direccion: [dir.address1, dir.address2].filter(Boolean).join(', '),
      cp_poblacion: [dir.zip, dir.city].filter(Boolean).join(' '),
      pais: dir.country || 'España',
    },
    lineas: (o.line_items || []).map((l) => ({
      titulo: l.title + (l.variant_title ? ` · ${l.variant_title}` : ''),
      unidades: l.quantity,
      precio: parseFloat(l.price || 0),
      iva: l.tax_lines && l.tax_lines[0] ? Math.round(parseFloat(l.tax_lines[0].rate || 0) * 100) : null,
    })),
    envio: parseFloat(o.total_shipping_price_set?.shop_money?.amount ?? o.shipping_lines?.[0]?.price ?? 0),
    descuento: parseFloat(o.total_discounts || 0),
    moneda: o.currency || cfg.moneda,
    pagado: o.financial_status === 'paid',
  } });
}
return salida;

// Pedidos de WooCommerce con la forma que usa el resto del workflow.
const cfg = $('Configuración').first().json;
const salida = [];
for (const item of $input.all()) {
  const o = item.json;
  if (!o || !o.id) continue;
  const b = o.billing || {};
  const meta = (o.meta_data || []).find((m) => /nif|cif|vat|dni/i.test(m.key));
  salida.push({ json: {
    id: String(o.id),
    numero_pedido: o.number || o.id,
    fecha: o.date_paid || o.date_created,
    cliente: {
      nombre: [b.first_name, b.last_name].filter(Boolean).join(' ') || b.company || 'Cliente',
      email: (b.email || '').trim().toLowerCase(),
      nif: (meta && String(meta.value)) || '',
      direccion: [b.address_1, b.address_2].filter(Boolean).join(', '),
      cp_poblacion: [b.postcode, b.city].filter(Boolean).join(' '),
      pais: b.country || 'España',
    },
    lineas: (o.line_items || []).map((l) => ({
      titulo: l.name,
      unidades: l.quantity,
      precio: l.quantity ? Math.round((parseFloat(l.total || 0) + parseFloat(l.total_tax || 0)) / l.quantity * 100) / 100 : 0,
      iva: null,
    })),
    envio: parseFloat(o.shipping_total || 0) + parseFloat(o.shipping_tax || 0),
    descuento: parseFloat(o.discount_total || 0),
    moneda: o.currency || cfg.moneda,
    pagado: ['processing', 'completed'].includes(o.status),
  } });
}
return salida;

const __estadoCliente = () => { const g = $getWorkflowStaticData('global'); const k = String($('Configuración').first().json.__token || '_'); g.clientes = g.clientes || {}; return (g.clientes[k] = g.clientes[k] || {}); };
// Asigna el número correlativo y calcula la base, el IVA por tipos y el total.
// Un pedido ya facturado NUNCA se vuelve a numerar: el número queda guardado por pedido.
const cfg = $('Configuración').first().json;
const estado = __estadoCliente();
estado.emitidas = estado.emitidas || {};
estado.contador = estado.contador || { anio: null, siguiente: 1 };

const pedidos = $input.all().map((i) => i.json).filter((p) => p && p.id);
if (!pedidos.length) throw new Error('No llegó ningún pedido');

const anio = new Date(cfg.ahora).getFullYear();
if (estado.contador.anio === null) estado.contador.anio = anio;
else if (cfg.reiniciar_cada_anio && estado.contador.anio !== anio) estado.contador = { anio, siguiente: 1 };

const redondear = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
const omitidos = { ya_facturados: 0, sin_pagar: 0, sin_lineas: 0 };
const pendientes = [];
for (const p of pedidos) {
  if (estado.emitidas[p.id]) { omitidos.ya_facturados += 1; continue; }
  if (!p.pagado) { omitidos.sin_pagar += 1; continue; }
  if (!Array.isArray(p.lineas) || !p.lineas.length) { omitidos.sin_lineas += 1; continue; }
  pendientes.push(p);
}
pendientes.sort((a, b) => Date.parse(a.fecha) - Date.parse(b.fecha));   // por fecha: el número sigue al tiempo
const aFacturar = pendientes.slice(0, cfg.max_por_ejecucion);

const facturas = [];
for (const p of aFacturar) {
  const brutas = p.lineas.map((l) => ({
    titulo: l.titulo || 'Producto',
    unidades: Number(l.unidades) || 1,
    precio: Number(l.precio) || 0,
    iva: (l.iva === null || l.iva === undefined) ? cfg.iva : Number(l.iva),
  }));
  if (Number(p.envio) > 0) {
    brutas.push({ titulo: 'Gastos de envío', unidades: 1, precio: Number(p.envio), iva: cfg.iva });
  }
  const totalBruto = brutas.reduce((s, l) => s + l.precio * l.unidades, 0);
  const descuento = Math.min(Number(p.descuento) || 0, totalBruto);

  // Todo en céntimos enteros: así la base y la cuota suman el total exacto, sin céntimos sueltos.
  const c = (n) => Math.round((Number(n) + Number.EPSILON) * 100);
  // Importe de cada línea = precio × unidades, lo que ve el cliente. El descuento sale aparte.
  const lineas = brutas.map((l) => ({ ...l, importe: c(l.precio * l.unidades) / 100 }));

  // El descuento se reparte entre los tipos de IVA según su peso; el último tipo absorbe el
  // redondeo para que la suma sea exactamente lo que pagó el cliente.
  const tipos = [];
  for (const l of lineas) {
    let t = tipos.find((x) => x.tipo === l.iva);
    if (!t) { t = { tipo: l.iva, bruto: 0 }; tipos.push(t); }
    t.bruto += c(l.precio * l.unidades);
  }
  tipos.sort((a, b) => b.tipo - a.tipo);
  const brutoC = tipos.reduce((s, t) => s + t.bruto, 0);
  const netoC = brutoC - c(descuento);
  let repartido = 0;
  tipos.forEach((t, i) => {
    t.neto = i === tipos.length - 1 ? netoC - repartido
      : Math.round(brutoC > 0 ? t.bruto - c(descuento) * (t.bruto / brutoC) : t.bruto);
    repartido += t.neto;
  });
  const porTipo = tipos.map((t) => {
    const baseC = cfg.precios_con_iva ? Math.round(t.neto / (1 + t.tipo / 100)) : t.neto;
    const cuotaC = cfg.precios_con_iva ? t.neto - baseC : Math.round(baseC * t.tipo / 100);
    return { tipo: t.tipo, base: baseC / 100, cuota: cuotaC / 100 };
  });
  const base = porTipo.reduce((s, t) => s + c(t.base), 0) / 100;
  const cuota = porTipo.reduce((s, t) => s + c(t.cuota), 0) / 100;

  const numero = `${cfg.serie}${estado.contador.anio}-${String(estado.contador.siguiente).padStart(cfg.digitos, '0')}`;
  estado.contador.siguiente += 1;
  estado.emitidas[p.id] = { numero, fecha: cfg.ahora, total: (c(base) + c(cuota)) / 100 };

  facturas.push({
    numero,
    pedido: p.id,
    numero_pedido: p.numero_pedido,
    fecha_pedido: p.fecha,
    fecha_factura: cfg.ahora,
    cliente: p.cliente,
    moneda: p.moneda || cfg.moneda,
    lineas,
    descuento: redondear(descuento),
    base, iva_por_tipo: porTipo, cuota,
    total: (c(base) + c(cuota)) / 100,
    enviar: Boolean(cfg.enviar_al_cliente && p.cliente && p.cliente.email),
  });
}

return [{ json: {
  ...cfg,
  hay_facturas: facturas.length > 0,
  facturas,
  en_espera: pendientes.length - aFacturar.length,
  omitidos,
  resumen: {
    emitidas: facturas.length,
    total: Math.round(facturas.reduce((s, f) => s + f.total, 0) * 100) / 100,
    base: Math.round(facturas.reduce((s, f) => s + f.base, 0) * 100) / 100,
    cuota: Math.round(facturas.reduce((s, f) => s + f.cuota, 0) * 100) / 100,
    sin_email: facturas.filter((f) => !f.enviar).length,
    pedidos_vistos: pedidos.length,
  },
} }];

// Monta el HTML del documento (una página por factura, y otra por albarán si toca)
// y lo deja como binario para que Gotenberg lo convierta en PDF.
const d = $('Numerar facturas').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const VERDE = '#235b54'; const TINTA = '#35322c'; const SUAVE = '#6e6a61'; const REGLA = '#e7e4dc';
const dinero = (n, m) => `${Number(n).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${m === 'EUR' ? '€' : m}`;
const dia = (f) => new Date(f).toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric' });

const pagina = (f, tipo) => {
  const conPrecios = tipo === 'factura';
  const filas = f.lineas.map((l) => `<tr>
<td style="padding:7px 0;border-bottom:1px solid ${REGLA}">${esc(l.titulo)}</td>
<td align="right" style="padding:7px 0;border-bottom:1px solid ${REGLA}">${l.unidades}</td>
${conPrecios ? `<td align="right" style="padding:7px 0;border-bottom:1px solid ${REGLA}">${dinero(l.precio, f.moneda)}</td>
<td align="right" style="padding:7px 0;border-bottom:1px solid ${REGLA}">${l.iva} %</td>
<td align="right" style="padding:7px 0;border-bottom:1px solid ${REGLA}">${dinero(l.importe, f.moneda)}</td>` : ''}
</tr>`).join('');

  const totales = conPrecios ? `<table width="100%" cellspacing="0" style="margin-top:14px">
${f.descuento ? `<tr><td align="right" style="padding:3px 0;color:${SUAVE}">Descuento</td><td align="right" width="120" style="padding:3px 0">−${dinero(f.descuento, f.moneda)}</td></tr>` : ''}
<tr><td align="right" style="padding:3px 0;color:${SUAVE}">Base imponible</td><td align="right" width="120" style="padding:3px 0">${dinero(f.base, f.moneda)}</td></tr>
${f.iva_por_tipo.map((t) => `<tr><td align="right" style="padding:3px 0;color:${SUAVE}">IVA ${t.tipo} % sobre ${dinero(t.base, f.moneda)}</td><td align="right" style="padding:3px 0">${dinero(t.cuota, f.moneda)}</td></tr>`).join('')}
<tr><td align="right" style="padding:10px 0 0;font-size:15px"><b>Total</b></td><td align="right" style="padding:10px 0 0;font-size:15px;color:${VERDE}"><b>${dinero(f.total, f.moneda)}</b></td></tr>
</table>` : '';

  return `<section style="page-break-after:always;padding:0 0 10px">
<table width="100%" cellspacing="0"><tr>
<td valign="top">
  <div style="font-family:Georgia,'Times New Roman',serif;font-size:20px;color:${VERDE}">${esc(d.emisor.nombre)}</div>
  <div style="font-size:11px;color:${SUAVE};line-height:1.5;padding-top:4px">
  NIF ${esc(d.emisor.nif)}<br>${esc(d.emisor.direccion)}<br>${esc(d.emisor.cp_poblacion)}<br>${esc(d.emisor.pais)}
  ${d.emisor.email ? `<br>${esc(d.emisor.email)}` : ''}${d.emisor.telefono ? ` · ${esc(d.emisor.telefono)}` : ''}</div>
</td>
<td valign="top" align="right">
  <div style="font-family:Georgia,'Times New Roman',serif;font-size:22px;color:${TINTA};text-transform:uppercase;letter-spacing:.04em">${tipo === 'factura' ? 'Factura' : 'Albarán'}</div>
  <div style="font-size:13px;color:${TINTA};padding-top:4px">${esc(f.numero)}${tipo === 'albaran' ? ' · A' : ''}</div>
  <div style="font-size:11px;color:${SUAVE};padding-top:2px">Fecha: ${dia(f.fecha_factura)}<br>Pedido: ${esc(f.numero_pedido)} · ${dia(f.fecha_pedido)}</div>
</td></tr></table>

<div style="border-top:1px solid ${REGLA};margin:18px 0 0;padding-top:14px">
<div style="font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:${SUAVE}">${tipo === 'factura' ? 'Destinatario' : 'Enviar a'}</div>
<div style="font-size:13px;color:${TINTA};line-height:1.5;padding-top:4px">
${esc(f.cliente.nombre)}${f.cliente.nif ? `<br>NIF ${esc(f.cliente.nif)}` : ''}<br>${esc(f.cliente.direccion)}<br>${esc(f.cliente.cp_poblacion)}${f.cliente.pais ? `<br>${esc(f.cliente.pais)}` : ''}</div>
</div>

<table width="100%" cellspacing="0" style="margin-top:20px;border-collapse:collapse;font-size:12px;color:${TINTA}">
<tr>
<th align="left" style="font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:${SUAVE};border-bottom:1px solid ${TINTA};padding-bottom:6px;font-weight:normal">Concepto</th>
<th align="right" style="font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:${SUAVE};border-bottom:1px solid ${TINTA};padding-bottom:6px;font-weight:normal">Uds.</th>
${conPrecios ? `<th align="right" style="font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:${SUAVE};border-bottom:1px solid ${TINTA};padding-bottom:6px;font-weight:normal">Precio</th>
<th align="right" style="font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:${SUAVE};border-bottom:1px solid ${TINTA};padding-bottom:6px;font-weight:normal">IVA</th>
<th align="right" style="font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:${SUAVE};border-bottom:1px solid ${TINTA};padding-bottom:6px;font-weight:normal">Importe</th>` : ''}
</tr>${filas}</table>
${totales}
<div style="margin-top:28px;font-size:10px;color:${SUAVE};line-height:1.6;border-top:1px solid ${REGLA};padding-top:10px">
${esc(d.texto_pie)}${tipo === 'factura' && d.precios_con_iva ? ' Los precios de la tienda incluyen el IVA; el desglose figura arriba.' : ''}
</div>
</section>`;
};

const tipos = d.documento === 'ambos' ? ['factura', 'albaran'] : [d.documento];

return d.facturas.map((f) => {
  const html = `<!doctype html><html><head><meta charset="utf-8"><style>
@page{size:A4;margin:14mm}
body{margin:0;font-family:Arial,Helvetica,sans-serif;color:${TINTA};-webkit-print-color-adjust:exact;print-color-adjust:exact}
section:last-child{page-break-after:auto}
</style></head><body>${tipos.map((t) => pagina(f, t)).join('')}</body></html>`;
  return {
    json: { ...f, gotenberg_url: d.gotenberg_url, nombre_pdf: `${d.documento === 'albaran' ? 'albaran' : 'factura'}-${f.numero}.pdf` },
    binary: { index_html: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html', fileName: 'index.html', fileExtension: 'html',
    } },
  };
});

// Deja cada factura lista para enviar al cliente, con el PDF adjunto.
const d = $('Numerar facturas').first().json;
const docs = $('Preparar documentos').all();
const pdfs = $input.all();
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const VERDE = '#235b54'; const TINTA = '#35322c'; const SUAVE = '#6e6a61'; const REGLA = '#e7e4dc'; const PAPEL = '#f4f3ef';
const dinero = (n, m) => `${Number(n).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${m === 'EUR' ? '€' : m}`;

const demo = d.fuente === 'demo' && Boolean(d.email_to);

return docs.map((doc, i) => {
  const f = doc.json;
  const salida = pdfs[i] || {};
  const bin = salida.binary || {};
  // Si Gotenberg no responde, se adjunta el documento en HTML antes que no mandar nada.
  const pdf = bin.factura_pdf || bin.data || null;
  const adjunto = pdf
    ? { ...pdf, fileName: f.nombre_pdf, fileExtension: 'pdf', mimeType: 'application/pdf' }
    : { ...(doc.binary.index_html), fileName: f.nombre_pdf.replace(/\.pdf$/, '.html') };

  const email_html = `<!doctype html><html><body style="margin:0;background:${PAPEL};font-family:Arial,Helvetica,sans-serif;color:${TINTA}">
<table width="100%" cellspacing="0"><tr><td align="center" style="padding:24px">
<table width="560" cellspacing="0" style="background:#fff;border-radius:12px"><tr><td style="padding:28px">
<div style="font-family:Georgia,'Times New Roman',serif;font-size:21px;color:${VERDE}">${esc(d.emisor.nombre)}</div>
<div style="font-family:Georgia,'Times New Roman',serif;font-size:22px;color:${TINTA};padding:10px 0 4px">Tu factura ${esc(f.numero)}</div>
<p style="font-size:15px;color:${TINTA};line-height:1.5;margin:8px 0 16px">
${esc(f.cliente.nombre ? `Hola, ${f.cliente.nombre.split(' ')[0]}:` : 'Hola:')} adjuntamos la factura del pedido ${esc(f.numero_pedido)} por ${dinero(f.total, f.moneda)}.</p>
<table width="100%" cellspacing="0" style="font-size:13px;color:${SUAVE}">
<tr><td style="padding:4px 0;border-bottom:1px solid ${REGLA}">Número</td><td align="right" style="padding:4px 0;border-bottom:1px solid ${REGLA};color:${TINTA}">${esc(f.numero)}</td></tr>
<tr><td style="padding:4px 0;border-bottom:1px solid ${REGLA}">Base imponible</td><td align="right" style="padding:4px 0;border-bottom:1px solid ${REGLA};color:${TINTA}">${dinero(f.base, f.moneda)}</td></tr>
<tr><td style="padding:4px 0;border-bottom:1px solid ${REGLA}">IVA</td><td align="right" style="padding:4px 0;border-bottom:1px solid ${REGLA};color:${TINTA}">${dinero(f.cuota, f.moneda)}</td></tr>
<tr><td style="padding:8px 0;font-size:15px;color:${TINTA}"><b>Total</b></td><td align="right" style="padding:8px 0;font-size:15px;color:${VERDE}"><b>${dinero(f.total, f.moneda)}</b></td></tr>
</table>
<p style="font-size:13px;color:${SUAVE};margin-top:18px">${esc(d.texto_pie)} Si necesitas cualquier cambio en los datos fiscales, responde a este correo.</p>
<div style="border-top:1px solid ${REGLA};margin-top:20px;padding-top:12px;font-size:11px;color:${SUAVE}">
${esc(d.emisor.nombre)} · NIF ${esc(d.emisor.nif)} · ${esc(d.emisor.cp_poblacion)}</div>
</td></tr></table></td></tr></table></body></html>`;

  return {
    json: { ...f, con_pdf: Boolean(pdf),
      // En modo demo los clientes son inventados: la factura te llega a ti, con el destinatario en el asunto.
      email_to: f.enviar ? (demo ? d.email_to : f.cliente.email) : '',
      email_from: d.email_from,
      asunto: `${demo ? `[Demo → ${f.cliente.email}] ` : ''}${d.emisor.nombre} · Factura ${f.numero}`, email_html },
    binary: { factura: adjunto },
  };
});

// Apunta qué facturas salieron por email y cuáles no (y por qué).
const previstas = $('Preparar envío').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json || {});
const enviadas = [];
const fallidas = [];
const sin_email = [];
previstas.forEach((f, i) => {
  if (!f.enviar) { sin_email.push({ numero: f.numero, cliente: f.cliente.nombre }); return; }
  const r = respuestas[i] || {};
  const error = r.error || r.errorMessage;
  if (error) {
    fallidas.push({ numero: f.numero, email: f.cliente.email,
      error: String(typeof error === 'object' ? error.message || JSON.stringify(error) : error).slice(0, 200) });
  } else {
    enviadas.push({ numero: f.numero, email: f.cliente.email, con_pdf: f.con_pdf });
  }
});
return [{ json: { hubo_envios: true, enviadas, fallidas, sin_email,
  sin_pdf: previstas.filter((f) => !f.con_pdf).length } }];

// Resumen para el dueño + CSV con el libro de facturas emitidas en esta pasada.
const d = $('Numerar facturas').first().json;
const ej = $input.first().json || { enviadas: [], fallidas: [], sin_email: [], sin_pdf: 0 };
const r = d.resumen;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const VERDE = '#235b54'; const TINTA = '#35322c'; const SUAVE = '#6e6a61';
const REGLA = '#e7e4dc'; const PAPEL = '#f4f3ef'; const ALERTA = '#8f2f24';
const dinero = (n) => `${Number(n || 0).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} €`;
const h3 = (t) => `<h3 style="font-family:Georgia,'Times New Roman',serif;font-size:17px;color:${VERDE};margin:24px 0 8px;font-weight:normal">${t}</h3>`;
const th = (t, der) => `<th align="${der ? 'right' : 'left'}" style="font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:${SUAVE};border-bottom:1px solid ${REGLA};padding:6px 0;font-weight:normal">${t}</th>`;
const td = (t, der) => `<td align="${der ? 'right' : 'left'}" style="font-size:13px;color:${TINTA};border-bottom:1px solid ${REGLA};padding:8px 0">${t}</td>`;
const cifra = (n, t, color) => `<td width="25%" style="padding:0 8px"><div style="font-family:Georgia,serif;font-size:30px;color:${color || VERDE};line-height:1">${n}</div><div style="font-size:12px;color:${SUAVE};padding-top:2px">${t}</div></td>`;

const enviadas = new Set(ej.enviadas.map((e) => e.numero));
const filas = d.facturas.slice(0, 15).map((f) => `<tr>${td(esc(f.numero))}${td(esc(f.cliente.nombre))}${td(dinero(f.total), 1)}` +
  td(enviadas.has(f.numero) ? 'enviada' : (f.enviar ? `<span style="color:${ALERTA}">no salió</span>` : 'sin email'), 1) + '</tr>').join('');

const cuerpo = d.facturas.length ? `<table width="100%" cellspacing="0" style="margin:4px 0 8px"><tr>
${cifra(r.emitidas, 'facturas')}${cifra(dinero(r.base), 'base imponible')}${cifra(dinero(r.cuota), 'IVA')}${cifra(dinero(r.total), 'total')}
</tr></table>
${h3('Emitidas')}
<table width="100%" cellspacing="0" style="border-collapse:collapse"><tr>${th('Número')}${th('Cliente')}${th('Total', 1)}${th('', 1)}</tr>${filas}</table>
${d.facturas.length > 15 ? `<p style="font-size:12px;color:${SUAVE};margin:8px 0 0">…y ${d.facturas.length - 15} más en el CSV adjunto.</p>` : ''}
${ej.fallidas.length ? `<p style="font-size:13px;color:${ALERTA};margin-top:16px">${ej.fallidas.length} factura(s) no se pudieron enviar (la factura está emitida igualmente): ${esc(ej.fallidas.slice(0, 3).map((f) => f.numero).join(', '))}</p>` : ''}
${ej.sin_email.length ? `<p style="font-size:13px;color:${SUAVE};margin-top:12px">${ej.sin_email.length} sin email del cliente: están en el CSV para enviarlas a mano.</p>` : ''}
${ej.sin_pdf ? `<p style="font-size:13px;color:${ALERTA};margin-top:12px">${ej.sin_pdf} salieron en HTML en vez de PDF: revisa que Gotenberg esté en marcha.</p>` : ''}
${d.en_espera ? `<p style="font-size:13px;color:${SUAVE};margin-top:12px">${d.en_espera} pedido(s) esperan a la próxima pasada por el tope de ${d.max_por_ejecucion}.</p>` : ''}
<p style="font-size:13px;color:${SUAVE};margin-top:20px">De ${r.pedidos_vistos} pedidos: ${d.omitidos.ya_facturados} ya facturados, ${d.omitidos.sin_pagar} sin pagar, ${d.omitidos.sin_lineas} sin líneas.</p>`
  : `<p style="font-size:15px;color:${TINTA};margin:0">No había pedidos nuevos que facturar. De ${r.pedidos_vistos} revisados: ${d.omitidos.ya_facturados} ya tenían factura y ${d.omitidos.sin_pagar} no están pagados.</p>`;

const email_html = `<!doctype html><html><body style="margin:0;background:${PAPEL};font-family:Arial,Helvetica,sans-serif;color:${TINTA}">
<table width="100%" cellspacing="0"><tr><td align="center" style="padding:24px">
<table width="680" cellspacing="0" style="background:#fff;border-radius:12px"><tr><td style="padding:28px">
<div style="font-family:Georgia,'Times New Roman',serif;font-size:22px;color:${VERDE}">Facturación · ${esc(d.emisor.nombre)}</div>
<div style="font-size:12px;color:${SUAVE};padding:2px 0 12px;border-bottom:1px solid ${REGLA}">${new Date(d.ahora).toLocaleString('es-ES', { dateStyle: 'long', timeStyle: 'short' })} · serie ${esc(d.serie)}</div>
${cuerpo}
<div style="border-top:1px solid ${REGLA};margin-top:24px;padding-top:12px;font-size:11px;color:${SUAVE}">Denoro Automations</div>
</td></tr></table></td></tr></table></body></html>`;

const telegram = `🧾 <b>Facturación · ${d.emisor.nombre}</b>\n` +
  `<b>Emitidas:</b> ${r.emitidas}${d.facturas.length ? ` (${d.facturas[0].numero} → ${d.facturas[d.facturas.length - 1].numero})` : ''}\n` +
  `<b>Base:</b> ${dinero(r.base)} · <b>IVA:</b> ${dinero(r.cuota)} · <b>Total:</b> ${dinero(r.total)}\n` +
  `<b>Enviadas:</b> ${ej.enviadas.length}` +
  (ej.fallidas.length ? ` · ⚠️ <b>Con error:</b> ${ej.fallidas.length}` : '') +
  (ej.sin_email.length ? ` · <b>Sin email:</b> ${ej.sin_email.length}` : '');

// ---- libro de facturas (CSV) ----
const celda = (v) => {
  const s = String(v ?? '').replace(/\r?\n\s*/g, ' ').trim();
  return /[";]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const cabecera = ['numero', 'fecha', 'pedido', 'cliente', 'nif', 'base', 'iva', 'cuota', 'total', 'estado'];
const lineas = [cabecera.join(';'), ...d.facturas.map((f) => [
  f.numero, new Date(f.fecha_factura).toISOString().slice(0, 10), f.numero_pedido, f.cliente.nombre,
  f.cliente.nif || '', f.base.toFixed(2).replace('.', ','),
  f.iva_por_tipo.map((t) => `${t.tipo}%`).join(' + '), f.cuota.toFixed(2).replace('.', ','),
  f.total.toFixed(2).replace('.', ','),
  enviadas.has(f.numero) ? 'enviada' : (f.enviar ? 'no enviada' : 'sin email'),
].map(celda).join(';'))];

// Si en esta pasada no se ha facturado nada, no se manda resumen (corre cada hora).
const hayAlgo = d.facturas.length > 0;
return [{
  json: { ...d, enviar_email: Boolean(d.enviar_email && hayAlgo), enviar_telegram: Boolean(d.enviar_telegram && hayAlgo), hay_algo: hayAlgo, asunto: `Denoro · ${r.emitidas} factura(s) de ${d.emisor.nombre}${r.emitidas ? ` · ${dinero(r.total)}` : ''}`,
    email_html, telegram, ejecucion: ej },
  binary: d.facturas.length ? { libro: {
    data: Buffer.from('﻿' + lineas.join('\n'), 'utf8').toString('base64'),
    mimeType: 'text/csv', fileName: `facturas-${new Date(d.ahora).toISOString().slice(0, 10)}.csv`, fileExtension: 'csv',
  } } : {},
}];

// (Se añade a cada automatización en su versión «para un cliente»)
// Guarda en denoro_estado lo que ha pasado en esta ejecución, para enseñarlo en el panel.
const d = $input.first()?.json || {};
const cfg = $('Configuración').first().json;
const txt = (s) => String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const titulo = txt(d.asunto).replace(/^[^\p{L}\p{N}]*Denoro · /u, '').replace(/^[^\p{L}\p{N}]+/u, '');
return [{ json: {
  clave: cfg.__clave, token: cfg.__token, snapshot: '',
  resumen: JSON.stringify({
    ultima: new Date().toISOString(), ok: true, modo: cfg.modo || null,
    titulo: (titulo || "Nada que facturar").slice(0, 200),
    texto: txt(d.telegram).slice(0, 1500),
    avisado: Boolean(d.asunto && (d.enviar_email || d.enviar_telegram)),
    demo: [cfg.fuente, cfg.destino].includes('demo'),
  }),
} }];
